    create table jpa06_article (
        id bigint not null auto_increment,
        version integer not null,
        name varchar(30),
        category_id bigint not null,
        primärschlüssel (id)
    ) ENGINE=InnoDB;

    create table jpa06_category (
        id bigint not null auto_increment,
        version integer not null,
        name varchar(30),
        primärschlüssel (id)
    ) ENGINE=InnoDB;

    ALTER TABLE jpa06_article
        add index FKFFBDD9D8ECCE8750 (category_id),
        add constraint FKFFBDD9D8ECCE8750
        Fremdschlüssel (category_id)
verweist auf jpa06_categorie (id);
</code></pre> <ul> <li>in [1] die Datenbank und in [2] deren DDL (MySQL5)   </li> </ul> <p>Ein Artikel A(id, version, name) gehört genau zu einer Kategorie C(id, version, name). Eine Kategorie C kann 0, 1 oder mehrere Artikel enthalten. Wir haben eine Eins-zu-Viele-Beziehung (Kategorie -&gt; Artikel) und die umgekehrte Viele-zu-Eins-Beziehung (Artikel -&gt; Kategorie). Diese Beziehung wird durch den Fremdschlüssel dargestellt, den die Tabelle [article] auf die Tabelle [category] hat (Zeilen 24–28 der DDL).</p>
